@RunWith(JUnit4.class)
public class Element_clone_TriageGen2Test {

    @Test
    public void testClone_NormalElement() {
        // Given
        Tag tag = Tag.valueOf("div");
        Attributes attributes = new Attributes();
        Element element = new Element(tag, "baseUri", attributes);

        // When
        Element clone = element.clone();

        // Then
        assertNotNull(clone);
        assertEquals(element.getClass(), clone.getClass());
        assertEquals(element.getClass().getName(), clone.getClass().getName());
    }

    @Test
    public void testClone_ElementWithClassNames() {
        // Given
        Tag tag = Tag.valueOf("div");
        Attributes attributes = new Attributes();
        attributes.put("class", "test-class");
        Element element = new Element(tag, "baseUri", attributes);

        // When
        Element clone = element.clone();

        // Then
        assertNotNull(clone);
        assertEquals(element.getClass(), clone.getClass());
        assertEquals(element.getClass().getName(), clone.getClass().getName());
        assertEquals(element.classNames(), clone.classNames());
    }

    @Test
    public void testClone_NullElement() {
        // Given
        Element element = null;

        // When & Then
        try {
            element.clone();
